#!/bin/sh
# Google search suggestions for /hoa/rental-restrictions/ (batch 2026-11-b). Run: sh pull-suggestions.sh > raw/google-suggestions-<date>.txt
# Adds seeds for the recorded-rules angle and named places to the 2026-11-04 list (from-2026-11-a/pull-suggestions.sh).
for q in "can an hoa ban rentals" "can an hoa ban rentals in south carolina" "can hoa change rental rules after purchase" "can hoa change rules after purchase south carolina" "hoa rental ban after purchase" "hoa amendment rental ban" "hoa vote to ban rentals" "hoa rental restrictions recorded" "hoa declaration rental restrictions" "deed restrictions rentals" "deed restrictions short term rentals" "covenants rental restrictions" "master deed rental restrictions" "condo minimum rental period" "condo minimum lease term" "myrtle beach condo rental restrictions" "myrtle beach condo rules" "myrtle beach hoa rules" "myrtle beach hoa rental" "carolina forest rental restrictions" "carolina forest hoa rules" "can you rent your house in carolina forest" "del webb myrtle beach rentals" "del webb rental restrictions" "55 community rental restrictions" "can you rent a house in a 55 community" "north myrtle beach condo rental rules" "barefoot resort rental restrictions" "grande dunes rental restrictions" "market common rental restrictions" "hoa owner occupancy requirement" "condo owner occupancy ratio" "fha condo owner occupancy" "non warrantable condo rental"; do
  printf '== %s\n' "$q"
  curl -sS "https://suggestqueries.google.com/complete/search?client=firefox&hl=en&gl=us&q=$(python3 -c "import urllib.parse,sys;print(urllib.parse.quote(sys.argv[1]))" "$q")"; echo
done
